def check_pending_returns(report):
    """
    Check for pending return requests in the sales audit report.

    Args:
        report (dict): The sales audit report.

    Returns:
        bool: True if there are pending return requests, False otherwise.
    """
    return report['returns']['pending_returns'] > 0
