def inspect_affected_orders(report):
    """
    Inspect the affected orders and summarize the likely issue for pending return requests.

    Args:
        report (dict): The sales audit report.

    Returns:
        str: A summary of the likely issue.
    """
    if report['returns']['pending_returns'] > 0:
        # Get the orders with pending returns
        pending_returns = report['returns']['pending_returns']
        orders_with_pending_returns = report['orders_by_status'].get('pending_returns', [])

        # Summarize the likely issue
        issue_summary = f"There are {pending_returns} pending return requests affecting {len(orders_with_pending_returns)} orders."
        if orders_with_pending_returns:
            issue_summary += f" The affected orders are: {', '.join([order['order_id'] for order in orders_with_pending_returns])}"
        return issue_summary
    else:
        return "No pending return requests found."
```

